  ('c1d62715-eba3-418c-bd1e-5f6e9d6f1cf1', $$Natuurkunde$$, $$VWO$$, $$Springende hydrogelballetjes$$, $$VWO Natuurkunde 2025-II$$),
  ('9ef25a4c-48f6-4215-b46f-f880cf0c7605', $$Natuurkunde$$, $$VWO$$, $$Sterrenlicht$$, $$VWO Natuurkunde 2025-II$$),
  ('9a3efc48-4b1b-4ca6-b9da-2a941d28cb50', $$Natuurkunde$$, $$VWO$$, $$Experiment van Millikan$$, $$VWO Natuurkunde 2025-II$$),
  ('6e47dbc9-1ece-4368-92d7-20a5c591754d', $$Natuurkunde$$, $$VWO$$, $$Lever zichtbaar maken$$, $$VWO Natuurkunde 2025-II$$),
